untScope":"new_writing","wordCountResourceRefs":[],"allowedWriteResourceRefs":[],"allowResourceDeletion":false,"minBodyCjk":1500,"maxBodyCjk":2000,"wordCountToleranceRatio":0,"completionEvidence":["bodyChineseCharacterCount","resourceHashes"],"prohibitRepetition":false,"requiresCompleteEnding":false,"reviewRequired":true,"narrativeAuditRequired":true,"narrativePerspective":{"mode":"limited","focusCharacterRef":"character:lin"},"repairRequired":true,"reviewScope":"saved_resources","reviewTargetResourceRefs":[],"reviewSourceKinds":["character","style","world"],"reviewScopeBound":true},"editor":{"novelId":"novel-mvf3hfjk-0ia52i","selectedText":"","chapterCount":1,"type":"none","title":""},"continuation":null,"conversation":[{"role":"user","text":"用传统写作模式续写第二章，保存为新章节。请先读取六人的角色设定、世界观、大纲、文风和前章，以林岚为第三人称有限视角，从20:05写到20:20，在旧渡口完成双印和是否启航的决定，正文1500—2000字。遵守角色秘密的信息边界，不凭空共享暗格或七分钟。写后自查人物、世界观、时间和视角，若有违背本次要求之处在本次任务内修正，再给出有实际资料依据的审校结果。"},{"role":"assistant","text":""}],"writingGuidance":[{"name":"mana-fiction-writing","text":"---
name: mana-fiction-writing
description: Draft and revise fiction using canonical resources and native approved changes.
